import { createClient, type SupabaseClient, type User } from '@supabase/supabase-js';
import { createHmac, timingSafeEqual } from 'crypto';
import type { Request, Response, NextFunction } from 'express';
import { logSanitizer } from '@/src/lib/logSanitizer';
import type { UserRole } from '@/src/types/auth';
import { logger } from '@/src/lib/logger';
import { deriveMentorAccountState } from '@/src/lib/adminMentorControl';

let supabaseAdmin: SupabaseClient | null = null;

export interface DemoTokenClaims {
  sub: string;
  email: string;
  role: UserRole;
  iat: number;
  exp: number;
}

const DEMO_TOKEN_PREFIX = 'skdemo.';
const DEMO_TOKEN_TTL_SECONDS = 24 * 60 * 60;
// Demo auth is opt-in AND fail-closed. Three conditions must ALL hold:
//
//   1. ENABLE_DEMO_PERSONAS=true  - an explicit human decision, not an accident
//                                   of having some other variable set.
//   2. A strong, externally supplied signing secret (DEMO_TOKEN_SECRET).
//      `DEMO_AUTH_SECRET` is accepted as a legacy alias so an existing local
//      setup keeps working, but a missing, short, or well-known value disables
//      demo auth entirely. There is deliberately no fallback default.
//   3. NODE_ENV is not production.
//
// Any one of them missing means `isDemoAuthEnabled()` is false, which makes
// `verifyDemoToken` reject every `skdemo.` token and closes
// `POST /api/auth/demo-login` with 404. There is no code path on which a
// missing secret silently degrades to a predictable one.
const FORBIDDEN_DEFAULT_SECRETS = new Set([
  'suggest-key-development-only',
  'development-only',
  'secret',
  'changeme',
  'demo',
]);

/** Minimum accepted length for DEMO_TOKEN_SECRET (256 bits of entropy is far more than enough). */
export const DEMO_TOKEN_SECRET_MIN_LENGTH = 32;

function readDemoTokenSecret(): string {
  const raw = (process.env.DEMO_TOKEN_SECRET ?? process.env.DEMO_AUTH_SECRET ?? '').trim();
  if (!raw) return '';
  if (raw.length < DEMO_TOKEN_SECRET_MIN_LENGTH) return '';
  if (FORBIDDEN_DEFAULT_SECRETS.has(raw.toLowerCase())) return '';
  return raw;
}

const DEMO_TOKEN_SECRET = readDemoTokenSecret();

/**
 * Explicit, opt-in switch for the demo personas.
 *
 * Only the exact string `true` enables it, so an unset variable, `0`, `false`
 * or a typo all leave demo auth off.
 */
export function isDemoPersonasExplicitlyEnabled(): boolean {
  return String(process.env.ENABLE_DEMO_PERSONAS ?? '').trim().toLowerCase() === 'true';
}

/**
 * Non-secret diagnostic used by the boot log so an operator can see exactly
 * which precondition is missing instead of guessing why demo login 404s.
 */
export function demoAuthDisabledReason(): string {
  if (process.env.NODE_ENV === 'production') return 'NODE_ENV=production';
  if (!isDemoPersonasExplicitlyEnabled()) return 'ENABLE_DEMO_PERSONAS is not "true"';
  if (!DEMO_TOKEN_SECRET) return 'DEMO_TOKEN_SECRET is missing, too short, or a known default';
  return '';
}

export function isDemoAuthEnabled(): boolean {
  return demoAuthDisabledReason() === '';
}

const encodeBase64Url = (value: Buffer): string =>
  value.toString('base64url');

const decodeBase64Url = (value: string): Buffer =>
  Buffer.from(value.replace(/-/g, '+').replace(/_/g, '/'), 'base64');

export function createDemoToken(claims: Omit<DemoTokenClaims, 'iat' | 'exp'>): string {
  const now = Math.floor(Date.now() / 1000);
  const payload: DemoTokenClaims = { ...claims, iat: now, exp: now + DEMO_TOKEN_TTL_SECONDS };
  const encodedPayload = encodeBase64Url(Buffer.from(JSON.stringify(payload)));
  const signature = encodeBase64Url(createHmac('sha256', DEMO_TOKEN_SECRET).update(encodedPayload).digest());
  return `${DEMO_TOKEN_PREFIX}${encodedPayload}.${signature}`;
}

export function verifyDemoToken(token: string): DemoTokenClaims | null {
  if (!isDemoAuthEnabled() || !token.startsWith(DEMO_TOKEN_PREFIX)) {
    return null;
  }

  const parts = token.slice(DEMO_TOKEN_PREFIX.length).split('.');
  if (parts.length !== 2) return null;

  const [encodedPayload, encodedSignature] = parts;
  const expectedSignature = createHmac('sha256', DEMO_TOKEN_SECRET).update(encodedPayload).digest();
  const actualSignature = decodeBase64Url(encodedSignature);
  if (expectedSignature.length !== actualSignature.length || !timingSafeEqual(expectedSignature, actualSignature)) {
    return null;
  }

  try {
    const payload = JSON.parse(decodeBase64Url(encodedPayload).toString('utf8')) as Partial<DemoTokenClaims>;
    if (
      typeof payload.sub !== 'string' ||
      typeof payload.email !== 'string' ||
      !['seeker', 'mentor', 'admin'].includes(payload.role || '') ||
      typeof payload.iat !== 'number' ||
      typeof payload.exp !== 'number' ||
      payload.exp <= Math.floor(Date.now() / 1000)
    ) {
      return null;
    }
    return payload as DemoTokenClaims;
  } catch {
    return null;
  }
}

export function getSupabaseAdmin(): SupabaseClient | null {
  if (supabaseAdmin) return supabaseAdmin;

  const url = process.env.VITE_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !key) {
    return null;
  }

  supabaseAdmin = createClient(url, key, {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
  });
  return supabaseAdmin;
}

interface AuthRequest extends Request {
  auth?: {
    user: User;
    roles: UserRole[];
  };
  requestId?: string;
  logStart?: number;
  /**
   * The exact bytes the client sent, captured by the JSON body's `verify` hook.
   *
   * Only the Razorpay webhook reads this, and only because the gateway signs
   * the raw bytes: re-serialising `req.body` would change the payload and the
   * signature could never verify. Left undefined on every other route.
   */
  rawBody?: Buffer;
}

function isUserRole(value: unknown): value is UserRole {
  return value === 'seeker' || value === 'mentor' || value === 'admin';
}

export async function requireAuth(
  req: AuthRequest,
  res: Response,
  next: NextFunction,
): Promise<void> {
  const authHeader = req.headers.authorization;
  const token = authHeader?.startsWith('Bearer ') ? authHeader.substring(7).trim() : null;
  const path = req.path || req.url || '';
  if (!token) {
    logger.auth('auth_missing_token', {
      requestId: req.requestId,
      path,
      result: 'failure',
      reason: 'AUTH_REQUIRED',
    });
    res.status(401).json({
      success: false,
      error: { code: 'AUTH_REQUIRED', message: 'A valid bearer token is required.' },
    });
    return;
  }

  const demoClaims = isDemoAuthEnabled() ? verifyDemoToken(token) : null;
  if (demoClaims) {
    req.auth = {
      user: {
        id: demoClaims.sub,
        email: demoClaims.email,
        aud: 'authenticated',
      } as User,
      roles: [demoClaims.role],
    };
    logger.auth('login_success', {
      requestId: req.requestId,
      userId: demoClaims.sub,
      role: demoClaims.role,
      path,
      result: 'success',
    });
    next();
    return;
  }

  const admin = getSupabaseAdmin();
  if (!admin) {
    logger.auth('auth_service_unavailable', {
      requestId: req.requestId,
      path,
      result: 'failure',
      reason: 'AUTH_SERVICE_UNAVAILABLE',
    });
    res.status(503).json({
      success: false,
      error: { code: 'AUTH_SERVICE_UNAVAILABLE', message: 'Authentication is not configured.' },
    });
    return;
  }

  try {
    const { data: { user }, error } = await admin.auth.getUser(token);
    if (error || !user) {
      logger.auth('login_failure', {
        requestId: req.requestId,
        path,
        result: 'failure',
        reason: error?.code || 'AUTH_INVALID',
      });
      res.status(401).json({
        success: false,
        error: { code: 'AUTH_INVALID', message: 'The provided token is invalid or expired.' },
      });
      return;
    }

    const { data: userRoles, error: rolesError } = await admin
      .from('user_roles')
      .select('role')
      .eq('user_id', user.id);

    if (rolesError) {
      logger.auth('role_lookup_failed', {
        requestId: req.requestId,
        userId: user.id,
        path,
        result: 'failure',
        reason: 'ROLE_LOOKUP_FAILED',
      });
      console.error('[Auth] Failed to fetch user roles:', rolesError.message);
      res.status(500).json({
        success: false,
        error: { code: 'ROLE_LOOKUP_FAILED', message: 'Unable to verify user roles.' },
      });
      return;
    }

    const roles: UserRole[] = (userRoles || [])
      .map((r: { role: string }) => r.role)
      .filter(isUserRole);

    req.auth = { user, roles };
    logger.auth('login_success', {
      requestId: req.requestId,
      userId: user.id,
       role: roles.includes('admin') ? 'admin' : roles.includes('mentor') ? 'mentor' : roles.includes('seeker') ? 'seeker' : undefined,
      path,
      result: 'success',
    });
    next();
  } catch (error) {
    logger.auth('login_failure', {
      requestId: req.requestId,
      path,
      result: 'failure',
      reason: 'AUTH_INVALID',
    });
    console.error('[Auth] Authentication failed:', logSanitizer.safeMessage(error));
    res.status(401).json({
      success: false,
      error: { code: 'AUTH_INVALID', message: 'The provided token is invalid or expired.' },
    });
  }
}

export async function requireAdmin(
  req: AuthRequest,
  res: Response,
  next: NextFunction,
): Promise<void> {
  if (!req.auth) {
    logger.auth('auth_missing', {
      requestId: req.requestId,
      path: req.path || req.url || '',
      result: 'failure',
      reason: 'AUTH_REQUIRED',
    });
    res.status(401).json({
      success: false,
      error: { code: 'AUTH_REQUIRED', message: 'Authentication required.' },
    });
    return;
  }

  if (!req.auth.roles.includes('admin')) {
    logger.auth('role_authorization_failure', {
      requestId: req.requestId,
      userId: req.auth.user.id,
      role: req.auth.roles.includes('mentor') ? 'mentor' : req.auth.roles.includes('seeker') ? 'seeker' : undefined,
      path: req.path || req.url || '',
      result: 'failure',
      reason: 'FORBIDDEN_ADMIN_REQUIRED',
    });
    res.status(403).json({
      success: false,
      error: { code: 'FORBIDDEN', message: 'Admin role required.' },
    });
    return;
  }

  next();
}

export function requireRole(role: UserRole): (req: AuthRequest, res: Response, next: NextFunction) => Promise<void> {
  return async (req, res, next) => {
    if (!req.auth) {
      logger.auth('auth_missing', {
        requestId: req.requestId,
        path: req.path || req.url || '',
        result: 'failure',
        reason: 'AUTH_REQUIRED',
      });
      res.status(401).json({
        success: false,
        error: { code: 'AUTH_REQUIRED', message: 'Authentication required.' },
      });
      return;
    }

    if (!req.auth.roles.includes(role) && !req.auth.roles.includes('admin')) {
      logger.auth('role_authorization_failure', {
        requestId: req.requestId,
        userId: req.auth.user.id,
      role: req.auth.roles.includes('mentor') ? 'mentor' : req.auth.roles.includes('seeker') ? 'seeker' : undefined,
      path: req.path || req.url || '',
      result: 'failure',
      reason: `FORBIDDEN_ROLE_${role.toUpperCase()}`,
      });
      res.status(403).json({
        success: false,
        error: { code: 'FORBIDDEN', message: `Role '${role}' required.` },
      });
      return;
    }

    next();
  };
}

export type { AuthRequest };

// ---------------------------------------------------------------------------
// requireActiveMentor
// ---------------------------------------------------------------------------
// A deactivated or suspended mentor keeps full READ access to their own
// history, but must not be able to perform normal operational actions through
// the mentor UI (prompt sections 5 and 7):
//   - create or modify operational availability
//   - create or edit active gigs
//   - receive new bookings
//
// This is a SERVER-SIDE gate reading the same columns the Admin writes, so the
// UI cannot be bypassed by calling the API directly.
//
// The Admin role is deliberately exempt: prompt section 3 gives the Admin
// permanent operational control over every mentor, including inactive ones.
export async function requireActiveMentor(
  req: AuthRequest,
  res: Response,
  next: NextFunction,
): Promise<void> {
  try {
    if (!req.auth) {
      res.status(401).json({
        success: false,
        error: { code: 'AUTH_REQUIRED', message: 'Authentication required.' },
      });
      return;
    }

    // Admins manage mentor resources through privileged operations and never
    // need to be blocked here.
    if (req.auth.roles.includes('admin')) {
      next();
      return;
    }

    const admin = getSupabaseAdmin();
    if (!admin) {
      // Without a configured service client the status cannot be proven, so
      // fail closed rather than silently allowing the action.
      res.status(503).json({
        success: false,
        error: { code: 'SERVICE_UNAVAILABLE', message: 'Mentor status cannot be verified right now.' },
      });
      return;
    }

    const userId = req.auth.user.id;

    const [{ data: mentorProfile, error: mpErr }, { data: profile, error: profileErr }] = await Promise.all([
      admin.from('mentor_profiles').select('approval_status, is_approved, is_active').eq('id', userId).maybeSingle(),
      admin.from('profiles').select('account_status, suspended_until').eq('id', userId).maybeSingle(),
    ]);

    if (mpErr) throw mpErr;
    if (profileErr) throw profileErr;

    if (!mentorProfile) {
      res.status(403).json({
        success: false,
        error: { code: 'MENTOR_PROFILE_NOT_FOUND', message: 'No mentor profile is associated with this account.' },
      });
      return;
    }

    const state = deriveMentorAccountState({
      approval_status: mentorProfile.approval_status ?? null,
      is_approved: mentorProfile.is_approved ?? null,
      is_active: mentorProfile.is_active ?? null,
      account_status: profile?.account_status ?? null,
      suspended_until: profile?.suspended_until ?? null,
    });

    if (!state.canPerformOperationalActions) {
      const reason = state.isSuspended
        ? 'Your account is suspended.'
        : state.isDeactivated
          ? 'Your mentor account has been deactivated by an administrator.'
          : 'Your mentor account is not active.';

      logger.auth('mentor_operational_blocked', {
        requestId: req.requestId,
        userId,
        role: 'mentor',
        path: req.path || req.url || '',
        result: 'failure',
        reason: state.isSuspended ? 'ACCOUNT_SUSPENDED' : state.isDeactivated ? 'ACCOUNT_DEACTIVATED' : 'MENTOR_INACTIVE',
      });

      res.status(403).json({
        success: false,
        error: { code: 'MENTOR_ACCOUNT_NOT_ACTIVE', message: reason },
      });
      return;
    }

    next();
  } catch (error) {
    logger.auth('mentor_operational_check_failed', {
      requestId: req.requestId,
      userId: req.auth?.user?.id,
      role: 'mentor',
      path: req.path || req.url || '',
      result: 'failure',
      reason: 'STATUS_CHECK_FAILED',
    });
    console.error('[Auth] Failed to verify mentor operational status:', logSanitizer.safeMessage(error));
    res.status(500).json({
      success: false,
      error: { code: 'STATUS_CHECK_FAILED', message: 'Unable to verify the mentor account status.' },
    });
  }
}

